ValidationRule.errorConditionFormula:
AND(
				NOT(ISNEW()),
				NOT(Bypass__c),
				NOT(
        AND(
            ISCHANGED(Bypass__c),
            PRIORVALUE(Bypass__c) = true
        )
    ),
				OR(
								AND(
												TEXT(StageName) = 'Instalado',
												NOT(ISCHANGED(StageName))
								),
								AND(
												TEXT(PRIORVALUE(StageName)) = "Instalado",
            ISCHANGED(StageName)
								)
				)
)
